  -- integrity advanced final - ord 38
  select case when md5(prompt) = 'eb6f9c95b7b7144ed4d73efa98252e29' and md5(coalesce(explanation, '')) = 'eeb64dc91c52a3ea189b87589e04304e' and md5(options::text) = md5('["A measurement of where the cement really is, since the calculation assumed a hole size nobody knows.", "Confirmation that the plug was balanced when pumping stopped, since a tag at the calculated depth proves the columns stood level.", "The bond between the cement and the wall, which is the property the length rule is buying and the only one that matters.", "The excess fraction that the next plug in the section should be pumped with."]'::jsonb::text) and answer_index = 0 then 'old'
