  if v_state is null then raise exception 'B4 fix integrity refused: no row for integrity advanced final - ord 38'; end if;
  if v_state = 'other' then raise exception 'B4 fix integrity refused: integrity advanced final - ord 38 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'The settled top has been computed and the string is on its way in to tag. What can the tag add that the calculation cannot?', options = '["A measurement of where the cement really is, since the calculation assumed a hole size nobody knows.", "Confirmation that the plug was balanced when pumping stopped, since a tag at the calculated depth proves the columns stood level.", "The bond between the cement and the wall, which is the property the length rule is buying and the only one that matters.", "A settle rate to carry to the next well, since the drop is the same on every job."]'::jsonb,
           answer_index = 0, explanation = 'The settled top is a prediction that assumes the hole is the size you told it, and the tag is the measurement. The gap between them is the best hole enlargement estimate that job will ever produce. A tag cannot prove balance or bond, and the settle rate is fixed by one well''s hole and stinger.'
     where app_slug = 'integrity' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 38 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix integrity refused: integrity advanced final - ord 38 updated % rows', v_count; end if;
