  if v_state is null then raise exception 'B4 fix integrity refused: no row for integrity advanced final - ord 42'; end if;
  if v_state = 'other' then raise exception 'B4 fix integrity refused: integrity advanced final - ord 42 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Between two runs on the same rule set, a rule in this engine changes its answer while the well in front of you has not changed at all. What should you go looking for?', options = '["A change in the excess, since excess moves the settled top and every length check in the rule set reads from it.", "A depth reference error, since a rule that moves without the well moving has usually been fed a mix of measured and vertical depths.", "A change in the engine version between the two runs of the case, which would reset each default threshold in the rule set.", "A verification flag, because each of them is a claim about evidence that a person entered by hand."]'::jsonb,
           answer_index = 3, explanation = 'Foundation on a plug, verifiedByLog on annular cement and element status on an envelope each move a threshold in the same way, and each is a claim a person entered by hand. The rule checks read the proposed plug interval rather than the settled top, so the excess cannot move them.'
